export class Money {
  #cents; #currency;
  constructor(cents, currency) {
    if (!Number.isInteger(cents) || cents < 0) throw new RangeError('cents');
    this.#cents = cents; this.#currency = currency;
    Object.freeze(this);
  }
  static equals(a, b) { return a.#cents === b.#cents && a.#currency === b.#currency; }
}

