import { Record, is } from 'immutable';

const Money = Record({ amount: 0, currency: 'EUR' });

const price = Money({ amount: 1500 });
const same = Money({ amount: 1500 });
console.log(is(price, same));                   // true - value equality
console.log(price.set('amount', 2000).amount);  // 2000; price untouched
